 12	
 13	const handlersByType = new Map<string, Set<Handler>>()
 14	const captureByType = new Map<string, boolean>()
 15	
 16	function getOrCreateSet(eventType: string, capture: boolean): Set<Handler> {
 17	  let set = handlersByType.get(eventType)
 18	  if (!set) {
 19	    set = new Set()
 20	    handlersByType.set(eventType, set)
 21	    captureByType.set(eventType, capture)
 22	    document.addEventListener(eventType, dispatch, capture)
 23	  }
 24	  return set
 25	}
