 27	function dispatch(event: Event): void {
 28	  const handlers = handlersByType.get(event.type)
 29	  if (handlers) {
 30	    // Safe to iterate directly — mutations (add/remove) only happen in
 31	    // setup/cleanup, not during dispatch. Set iteration is stable for
 32	    // entries that existed when iteration began.
 33	    handlers.forEach((handler) => {
 34	      handler(event)
 35	    })
 36	  }
 37	}
